// Mode: Run Once for All Items

function cleanText(text) {
  if (!text || typeof text !== 'string') {
    return '';
  }

  let cleaned = text;

  // Normalize line breaks
  cleaned = cleaned.replace(/\r\n/g, '\n');
  cleaned = cleaned.replace(/\r/g, '\n');

  // Remove repeated line breaks
  cleaned = cleaned.replace(/\n{2,}/g, '\n');

  // Fix broken line wrapping
  cleaned = cleaned.replace(/([^\n])\n([^\n])/g, '$1 $2');

  // Remove multiple spaces
  cleaned = cleaned.replace(/\s{2,}/g, ' ');

  // Remove page noise
  cleaned = cleaned.replace(/Page \d+ of \d+/gi, '');
  cleaned = cleaned.replace(/Session \d{2}-\d{2}/gi, '');
  cleaned = cleaned.replace(/Course Syllabus/gi, '');

  return cleaned.trim();
}

const items = $input.all();

return items.map(item => {
  const raw = item.json.text || '';   // ✅ FIX HERE

  return {
    json: {
      cleanedText: cleanText(raw)
    }
  };
});

// Mode: Run Once for All Items

function safeParse(jsonString) {
  try {
    return JSON.parse(jsonString);
  } catch (e) {
    throw new Error('Failed to parse Gemini JSON: ' + e.message);
  }
}

const items = $input.all();

// 🔥 Step 1: Extract Gemini text properly
let rawText =
  items[0].json.content?.parts?.[0]?.text ||
  items[0].json.text ||
  items[0].json.response ||
  '';

// 🔥 Step 2: Remove markdown code block if present
rawText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// 🔥 Step 3: Parse JSON
const parsed = safeParse(rawText);

// Ensure assignments array exists
const assignments = Array.isArray(parsed.assignments)
  ? parsed.assignments
  : [];

// Optional course name
const courseName = items[0].json.course_name || 'Class X';

// 🔥 Date normalization helper
function toISO(dateString) {
  if (!dateString) return null;

  if (/^\d{4}-\d{2}-\d{2}$/.test(dateString.trim())) {
    return dateString.trim();
  }

  const m = dateString.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-]?(\d{2,4})?/);
  if (!m) return null;

  let month = parseInt(m[1], 10);
  let day = parseInt(m[2], 10);
  let year = m[3] ? parseInt(m[3], 10) : new Date().getFullYear();

  if (year < 100) year += 2000;

  return new Date(year, month - 1, day).toISOString().slice(0, 10);
}

// 🔥 Step 4: Normalize output
const normalized = assignments.map(a => {
  const iso = toISO(a.due_date);

  let hours = Number(a.estimated_hours);
  if (!Number.isFinite(hours) || hours <= 0) hours = 3;

  let priority = 'medium';
  if (iso) {
    const diffDays =
      (new Date(iso).getTime() - Date.now()) / (1000 * 60 * 60 * 24);

    if (diffDays <= 7) priority = 'high';
    else if (diffDays <= 21) priority = 'medium';
    else priority = 'low';
  }

  return {
    json: {
      title: a.title || 'Untitled',
      due_date: iso,
      description: a.description || '',
      estimated_hours: hours,
      course_name: courseName,
      priority
    }
  };
});

return normalized;

const items = $input.all();

function createSingleSession(a, index) {
  const sessionLengthHours = Math.min(a.estimated_hours || 3, 2); 
  // optional: cap session duration to 2 hours max

  let baseDate;

  if (a.due_date) {
    baseDate = new Date(a.due_date + 'T09:00:00');
    baseDate.setDate(baseDate.getDate() - 2); // 2 days before exam/deadline
  } else {
    baseDate = new Date();
    baseDate.setDate(baseDate.getDate() + index + 1);
  }

  const startDateTime = new Date(baseDate);
  startDateTime.setHours(18, 0, 0, 0);

  const endDateTime = new Date(startDateTime);
  endDateTime.setHours(endDateTime.getHours() + sessionLengthHours);

  return {
    json: {
      type: 'study_session',
      assignment_title: a.title,
      course_name: a.course_name,
      priority: a.priority,
      start: startDateTime.toISOString(),
      end: endDateTime.toISOString(),
      due_date: a.due_date,
      estimated_hours: sessionLengthHours,
      description: `Single study session for "${a.title}".`
    }
  };
}

const output = [];

items.forEach((item, index) => {
  output.push(createSingleSession(item.json, index));
});

return output;

const items = $input.all();

function normalize(j) {
  const isStudySession =
    j.summary?.toLowerCase?.().includes('study') ||
    j.description?.includes('study session') ||
    j.assignment_title !== undefined;

  const start = j.start?.dateTime || j.start || '';
  const end = j.end?.dateTime || j.end || '';

  const title = j.summary || j.assignment_title || j.title || '';

  let course_name = '';
  let priority = '';

  if (j.description) {
    const courseMatch = j.description.match(/Course:\s*(.*)/);
    const priorityMatch = j.description.match(/Priority:\s*(.*)/);

    if (courseMatch) course_name = courseMatch[1].split('\n')[0].trim();
    if (priorityMatch) priority = priorityMatch[1].split('\n')[0].trim();
  }

  return {
    type: isStudySession ? 'study_session' : 'assignment_deadline',
    title,
    course_name,
    priority,
    start,
    end,
    due_date: j.due_date || '',
    description: j.description || '',
    calendar_event_id: j.id || ''
  };
}

return items.map(item => {
  const j = item.json;

  return {
    json: normalize(j)
  };
});

const items = $input.all();

let assignmentCount = 0;
let studyCount = 0;
let unknownCount = 0;

for (const item of items) {
  const t = item.json?.type;

  if (t === 'assignment_deadline') {
    assignmentCount++;
  } else if (t === 'study_session') {
    studyCount++;
  } else {
    unknownCount++;
  }
}

return [
  {
    json: {
      message: 'Planner run summary',
      assignment_events: assignmentCount,
      study_session_events: studyCount,
      unknown_events: unknownCount,
      total_events_logged: items.length
    }
  }
];
